/**
 * Reads the generated skill markdown files and splits them into sections.
 */
import { readFileSync, existsSync, readdirSync, statSync } from 'fs';
import { join } from 'path';
function extractKeywords(title) {
    return title
        .toLowerCase()
        .replace(/[^a-z0-9\s-]/g, '')
        .split(/\s+/)
        .filter(w => w.length > 2);
}
/**
 * Recursively find all .md files in a directory.
 */
function findMarkdownFiles(dir) {
    const files = [];
    if (!existsSync(dir))
        return files;
    for (const entry of readdirSync(dir)) {
        const full = join(dir, entry);
        if (statSync(full).isDirectory()) {
            files.push(...findMarkdownFiles(full));
        }
        else if (entry.endsWith('.md')) {
            files.push(full);
        }
    }
    return files;
}
/**
 * Split a markdown file into sections at ## boundaries.
 */
function splitIntoSections(content, sourceFile) {
    const sections = [];
    const parts = content.split(/^## /m);
    for (const part of parts) {
        const trimmed = part.trim();
        if (!trimmed)
            continue;
        const newlineIdx = trimmed.indexOf('\n');
        if (newlineIdx === -1) {
            // Single-line section (just a heading)
            sections.push({
                title: trimmed,
                body: '',
                sourceFile,
                keywords: extractKeywords(trimmed),
            });
        }
        else {
            const title = trimmed.slice(0, newlineIdx).trim();
            const body = trimmed.slice(newlineIdx + 1).trim();
            sections.push({
                title,
                body,
                sourceFile,
                keywords: extractKeywords(title),
            });
        }
    }
    return sections;
}
/**
 * Load all skill markdown files and return content sections.
 * @param skillDir - Direct path to the skills directory (e.g. `data/skills/`)
 */
export function loadContent(skillDir) {
    if (!existsSync(skillDir)) {
        console.warn(`[loader] Skill directory not found: ${skillDir}`);
        console.warn('[loader] Data files may be missing — try reinstalling the package.');
        return [];
    }
    const mdFiles = findMarkdownFiles(skillDir);
    const sections = [];
    for (const filePath of mdFiles) {
        try {
            const content = readFileSync(filePath, 'utf-8');
            // Use relative path from skill dir as source file name
            const relPath = filePath.slice(skillDir.length + 1).replace(/\\/g, '/');
            sections.push(...splitIntoSections(content, relPath));
        }
        catch (err) {
            console.warn(`[loader] Failed to read ${filePath}: ${err.message}`);
        }
    }
    console.error(`[loader] Loaded ${sections.length} sections from ${mdFiles.length} files`);
    return sections;
}
